--
-- Structure for view `active_academic_structure`
--
DROP TABLE IF EXISTS `active_academic_structure`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `active_academic_structure`  AS SELECT `p`.`program_id` AS `program_id`, `p`.`program_name` AS `program_name`, `ay`.`academic_year_id` AS `academic_year_id`, `ay`.`academic_year` AS `academic_year`, `s`.`semester_id` AS `semester_id`, `s`.`semester_number` AS `semester_number`, `ys`.`section_id` AS `section_id`, `ys`.`year_level` AS `year_level`, `ys`.`section_name` AS `section_name` FROM (((`programs` `p` join `academic_years` `ay` on(`p`.`program_id` = `ay`.`program_id`)) join `semesters` `s` on(`ay`.`academic_year_id` = `s`.`academic_year_id`)) join `year_sections` `ys` on(`s`.`semester_id` = `ys`.`semester_id` and `p`.`program_id` = `ys`.`program_id`)) WHERE `p`.`status` = 'active' AND `ay`.`status` = 'active' AND `ay`.`is_current` = 1 AND `s`.`status` = 'active' AND `s`.`is_current` = 1 AND `ys`.`status` = 'active' ;

-- --------------------------------------------------------

--
-- Structure for view `active_invites`
--
DROP TABLE IF EXISTS `active_invites`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `active_invites`  AS SELECT `invites`.`id` AS `id`, `invites`.`token` AS `token`, `invites`.`invite_type` AS `invite_type`, `invites`.`expires_at` AS `expires_at`, `invites`.`current_uses` AS `current_uses`, `invites`.`max_uses` AS `max_uses`, `invites`.`created_by` AS `created_by`, `invites`.`created_at` AS `created_at`, CASE WHEN `invites`.`expires_at` <= current_timestamp() THEN 'expired' WHEN `invites`.`current_uses` >= `invites`.`max_uses` THEN 'used_up' ELSE 'active' END AS `status` FROM `invites` WHERE `invites`.`expires_at` > current_timestamp() AND `invites`.`current_uses` < `invites`.`max_uses` ORDER BY `invites`.`created_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `attendance_summary`
--
DROP TABLE IF EXISTS `attendance_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `attendance_summary`  AS SELECT `a`.`student_id` AS `student_id`, `s`.`first_name` AS `first_name`, `s`.`last_name` AS `last_name`, `s`.`course` AS `course`, `s`.`year_section` AS `year_section`, cast(`a`.`timestamp` as date) AS `date`, `a`.`status` AS `status`, `a`.`timestamp` AS `timestamp`, `a`.`session_id` AS `session_id` FROM (`attendance` `a` join `students` `s` on(`a`.`student_id` = `s`.`student_id`)) ORDER BY `a`.`timestamp` DESC ;

